// One item per topic with ready-made arXiv and OpenAlex queries.
const s = $('Set digest settings').first().json;
const topics = String(s.topics || '').split(/\n|;/).map(t => t.trim()).filter(Boolean);
const cats = String(s.arxiv_categories || '').split(/[\s,]+/).filter(Boolean);
const since = new Date(Date.now() - (Number(s.days_back) || 7) * 864e5).toISOString().slice(0, 10);
return topics.map(topic => {
  const words = topic.includes(' ') ? `all:"${topic.replace(/"/g, '')}"` : `all:${topic}`;
  const q = cats.length ? `(${words}) AND (${cats.map(c => 'cat:' + c).join(' OR ')})` : words;
  return { json: { topic, since, arxiv_query: q, per_topic: Number(s.max_per_topic) || 25 } };
});

const dec = s => String(s || '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const tag = (x, t) => (x.match(new RegExp('<' + t + '[^>]*>([\\s\\S]*?)</' + t + '>')) || [])[1] || '';
function parseArxiv(xml, topic) {
  return String(xml || '').split('<entry>').slice(1).map(e => {
    const idUrl = dec(tag(e, 'id'));
    const id = idUrl.replace(/^https?:\/\/arxiv\.org\/abs\//, '').replace(/v\d+$/, '');
    const authors = [...e.matchAll(/<name>([\s\S]*?)<\/name>/g)].map(m => dec(m[1]));
    const pdf = (e.match(/<link[^>]*title="pdf"[^>]*href="([^"]+)"/) || e.match(/<link[^>]*href="([^"]+)"[^>]*title="pdf"/) || [])[1] || '';
    return { paper_id: 'arxiv:' + id, title: dec(tag(e, 'title')), abstract: dec(tag(e, 'summary')), authors: authors.slice(0, 8).join(', ') + (authors.length > 8 ? ' et al.' : ''),
      published: dec(tag(e, 'published')).slice(0, 10), url: 'https://arxiv.org/abs/' + id, pdf_url: pdf.replace('http://', 'https://'),
      doi: dec(tag(e, 'arxiv:doi')).toLowerCase(), venue: 'arXiv ' + ((e.match(/<arxiv:primary_category[^>]*term="([^"]+)"/) || [])[1] || ''),
      citations: '', source: 'arXiv', topic };
  }).filter(p => p.title && !/^error$/i.test(p.title));
}

// Parse each topic's Atom feed, keep the look-back window, de-duplicate across topics.
const topics = $('One item per topic').all().map(i => i.json);
const since = topics[0]?.since || '1900-01-01';
const seen = new Set(); const out = [];
$input.all().forEach((item, i) => {
  for (const p of parseArxiv(item.json.data, topics[i]?.topic || '')) {
    if (p.published < since || seen.has(p.paper_id)) continue;
    seen.add(p.paper_id); out.push({ json: p });
  }
});
return out;

