const s = $('Set digest settings').first().json;
const papers = $('Keep the newest papers').all().map(i => i.json);
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map((it, i) => ({ ...papers[i], ...(it.json.output || {}) }))
  .filter(r => Number(r.relevance) >= (Number(s.min_relevance) || 6)).sort((a, b) => b.relevance - a.relevance);
if (!rows.length) return [];
const html = `<div style="font-family:Arial,sans-serif;max-width:700px"><h2>📚 ${rows.length} papers worth reading this week</h2>` +
  rows.map(r => `<p><a href="${esc(r.url)}"><b>${esc(r.title)}</b></a> <span style="color:#64748b">(${r.relevance}/10 · ${esc(r.published)} · ${esc(r.topic)})</span><br>` +
  `${esc(r.tldr)}<br><i style="color:#475569">${esc(r.why)}</i></p>`).join('') +
  '<p style="color:#94a3b8;font-size:11px">AI summaries of abstracts. Check the paper before citing it.</p></div>';
return [{ json: { subject: `Research digest: ${rows.length} papers for you`, html } }];
